import com.tom_roush.pdfbox.android.PDFBoxResourceLoader;import com.tom_roush.pdfbox.pdmodel.PDDocument;import com.tom_roush.pdfbox.text.PDFTextStripper;import com.tom_roush.pdfbox.io.MemoryUsageSetting;import java.io.*;
public class PdfExtractionCheck {
 public static void main(String[] a)throws Exception {PDFBoxResourceLoader.init(new android.content.Context());try(PDDocument doc=PDDocument.load(new File(a[0]),MemoryUsageSetting.setupMixed(8388608))){if(doc.getNumberOfPages()!=3)throw new AssertionError("pages");PDFTextStripper s=new PDFTextStripper();s.setSortByPosition(true);s.setStartPage(1);s.setEndPage(1);String first=s.getText(doc);if(!first.contains("Seeky searchable text"))throw new AssertionError(first);System.out.println("PASS bundled PDF engine extracts real page text using bundled assets (host shims only)");s.setStartPage(2);s.setEndPage(2);String second=s.getText(doc);if(!second.contains("Deep search second page")||second.contains("Seeky searchable"))throw new AssertionError(second);System.out.println("PASS per-page extraction separates search offsets and pages");s.setStartPage(3);s.setEndPage(3);if(!s.getText(doc).trim().isEmpty())throw new AssertionError("blank page");System.out.println("PASS page without text has no invented text or OCR");}}
}
